// Post Formatter (robust parser + quality gates for 500–3000 chars on post_content ONLY)

// ---------- Parse AI output ----------
let aiData;

function stripCodeFences(s) {
  return String(s)
    .trim()
    .replace(/^```(?:json)?\s*/i, "")
    .replace(/```$/i, "")
    .trim();
}

try {
  const item = $input.all()?.[0]?.json ?? {};
  let raw = item.output ?? item; // prefer .output, fallback to whole item

  // If string, parse JSON (and strip code fences just in case)
  if (typeof raw === "string") {
    const cleaned = stripCodeFences(raw);
    raw = JSON.parse(cleaned);
  }

  // If the model incorrectly wrapped again as { output: {...} }, unwrap it
  if (raw && typeof raw === "object" && raw.output && typeof raw.output === "object") {
    raw = raw.output;
  }

  if (!raw || typeof raw !== "object") {
    throw new Error("Missing or invalid AI payload (expected object)");
  }

  aiData = raw;
} catch (error) {
  throw new Error("Failed to parse AI output: " + error.message);
}

// ---------- Extract + normalize ----------
const postContent = String(aiData.post_content ?? "").trim();

const hashtagsRaw = Array.isArray(aiData.hashtags) ? aiData.hashtags : [];
const firstCommentCta = String(aiData.first_comment_cta ?? "").trim();
const imageQuery = String(aiData.image_query ?? "").trim();

// Normalize hashtags: trim, ensure "#", de-dupe, keep order
const normalizedHashtags = Array.from(
  new Set(
    hashtagsRaw
      .map(h => String(h ?? "").trim())
      .filter(Boolean)
      .map(h => (h.startsWith("#") ? h : `#${h.replace(/^#+/, "")}`))
  )
);

// Enforce 3–5 (don't invent hashtags here; just clamp and warn later)
const clampedHashtags = normalizedHashtags.slice(0, 5);
const hashtagString = clampedHashtags.join(" ");

// Ensure post_content does NOT already include hashtags; if it does, don't duplicate
const postAlreadyHasHashtags =
  clampedHashtags.length > 0 &&
  clampedHashtags.every(tag => postContent.includes(tag));

// Assemble final post for publishing (hashtags appended)
const finalPost =
  postAlreadyHasHashtags || clampedHashtags.length === 0
    ? postContent
    : postContent + '\n\n' + hashtagString;

// ---------- Metrics ----------
// IMPORTANT: character constraint applies to post_content only (NOT final_post)
const characterCount = postContent.length;

// Word count guard (avoid 1 for empty)
const wordCount = postContent.trim()
  ? postContent.trim().split(/\s+/).length
  : 0;

// ---------- Quality checks ----------
const MIN_CHARS = 500;
const MAX_CHARS = 3000;

const isWithinLimit = characterCount >= MIN_CHARS && characterCount <= MAX_CHARS;
const hasHashtags = clampedHashtags.length >= 3 && clampedHashtags.length <= 5;

// Forbidden patterns should apply to post_content (your rules target the post body)
const hasEmDash = postContent.includes("—");

// Emoji count should apply to post_content (hashtags don't matter)
const emojiCount = (
  postContent.match(
    /[\u{1F600}-\u{1F64F}\u{1F300}-\u{1F5FF}\u{1F680}-\u{1F6FF}\u{1F1E0}-\u{1F1FF}\u{2600}-\u{26FF}\u{2700}-\u{27BF}]/gu
  ) || []
).length;

const hasExcessiveEmojis = emojiCount > 1;

// Enforce "hashtags not inside post_content"
const postContainsHashtags = clampedHashtags.some(tag => postContent.includes(tag));

// Optional: make this true if you always require a first comment CTA
const requiresFirstComment = false;
const hasFirstCommentCta = firstCommentCta.length > 0;

const passesQualityCheck =
  isWithinLimit &&
  hasHashtags &&
  !hasEmDash &&
  !hasExcessiveEmojis &&
  !postContainsHashtags &&
  (!requiresFirstComment || hasFirstCommentCta);

// ---------- Warnings ----------
const warnings = [
  characterCount < MIN_CHARS ? `Post too short (${characterCount} chars, need ${MIN_CHARS}+)` : null,
  characterCount > MAX_CHARS ? `Post too long (${characterCount} chars, max ${MAX_CHARS})` : null,
  clampedHashtags.length < 3 ? `Too few hashtags (${clampedHashtags.length}, need 3-5)` : null,
  clampedHashtags.length > 5 ? `Too many hashtags (${clampedHashtags.length}, max 5)` : null,
  postContainsHashtags ? `post_content contains hashtags; remove hashtags from post_content` : null,
  hasEmDash ? `Post contains em dash (—), remove it` : null,
  hasExcessiveEmojis ? `Post has ${emojiCount} emojis (max 1)` : null,
  requiresFirstComment && !hasFirstCommentCta ? `Missing first comment CTA` : null,
].filter(Boolean);

// ---------- Return (n8n Code v2 format) ----------
return [{
  json: {
    // Publish-ready
    final_post: finalPost,

    // Components
    post_content: postContent,
    hashtags: clampedHashtags,
    hashtag_string: hashtagString,

    first_comment_cta: firstCommentCta,
    has_first_comment: hasFirstCommentCta,

    image_query: imageQuery,

    // Metadata (character_count is post_content only)
    character_count: characterCount,
    word_count: wordCount,
    hashtag_count: clampedHashtags.length,
    emoji_count: emojiCount,

    // Checks
    is_within_limit: isWithinLimit,
    has_minimum_hashtags: hasHashtags,
    post_contains_hashtags: postContainsHashtags,
    has_forbidden_em_dash: hasEmDash,
    has_excessive_emojis: hasExcessiveEmojis,
    passes_quality_check: passesQualityCheck,

    generated_at: new Date().toISOString(),
    warnings
  }
}];

// Get the image link
let imageUrl = $('Limit to One Post').first().json['Image link for your post'];

// Clean the URL
imageUrl = imageUrl.trim();

// Convert common sharing links to direct download links

// Google Drive
if (imageUrl.includes('drive.google.com/file/d/')) {
  const fileIdMatch = imageUrl.match(/\/d\/([^\/]+)/);
  if (fileIdMatch) {
    imageUrl = `https://drive.google.com/uc?export=download&id=${fileIdMatch[1]}`;
  }
}

// Dropbox - change dl=0 to dl=1
if (imageUrl.includes('dropbox.com') && imageUrl.includes('dl=0')) {
  imageUrl = imageUrl.replace('dl=0', 'dl=1');
}

// Imgur - convert to direct image link
if (imageUrl.includes('imgur.com/') && !imageUrl.includes('i.imgur.com')) {
  imageUrl = imageUrl.replace('imgur.com/', 'i.imgur.com/') + '.jpg';
}

// OneDrive/SharePoint
if (imageUrl.includes('sharepoint.com') || imageUrl.includes('1drv.ms')) {
  // OneDrive links need special handling - append ?download=1
  imageUrl = imageUrl.split('?')[0] + '?download=1';
}

return {
  json: {
    original_url: $('Limit to One Post').first().json['Image link for your post'],
    direct_download_url: imageUrl
  }
};

// Get data from previous n8n node
const inputData = $input.all();

// Get the JSON data from the first item
const jsonData = inputData[0].json;

// Navigate to the results array
const results = jsonData.results;

// Create output object
const output = {
  results: {}
};

// Process each result
results.forEach((item, index) => {
  output.results[`results[${index}]`] = {
    download: item.links.download,
    alt_description: item.alt_description,
    description: item.description
  };
});

// Return the data for n8n
return [{ json: output }];
